let ctx,noiseBuffer,enabled=localStorage.getItem('mq.sound')!=='off',music=localStorage.getItem('mq.music')!=='off',master,musicBus,lastResume=0,nextBeat=0,step=0,mode='',lastKey='',lastSecond=-1,lastResultCue=-1;
export function soundEnabled(){return enabled;}
export function musicEnabled(){return music;}
