export function toggleMusic(){music=!music;localStorage.setItem('mq.music',music?'on':'off');if(music)unlockAudio();else if(musicBus&&ctx)musicBus.gain.setTargetAtTime(0,ctx.currentTime,.03);return music;}
export function toggleSound(){enabled=!enabled;localStorage.setItem('mq.sound',enabled?'on':'off');if(enabled){unlockAudio();playSound('correct');}else if(master&&ctx)master.gain.setTargetAtTime(0,ctx.currentTime,.03);return enabled;}
export function unlockAudio(){if(!enabled&&!music)return;try{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;if(!ctx){ctx=new AC();master=ctx.createGain();master.gain.value=enabled?.65:0;const limiter=ctx.createDynamicsCompressor();limiter.threshold.value=-14;limiter.ratio.value=5;limiter.connect(ctx.destination);master.connect(limiter);musicBus=ctx.createGain();musicBus.gain.value=0;musicBus.connect(limiter);}master.gain.setTargetAtTime(enabled?.65:0,ctx.currentTime,.02);if(ctx.state==='suspended'){const now=Date.now();if(now-lastResume>1000){lastResume=now;ctx.resume().catch(()=>{});}}}catch{}}
function tone(f,t,d,amp,type='sine',bus=master){if(!ctx||!bus)return;const o=ctx.createOscillator(),g=ctx.createGain();o.type=type;o.frequency.setValueAtTime(f,t);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(Math.max(.0002,amp),t+.008);g.gain.exponentialRampToValueAtTime(.0001,t+d);o.connect(g).connect(bus);o.onended=()=>{try{o.disconnect();g.disconnect();}catch{}};o.start(t);o.stop(t+d+.015);}
