export function playSound(type){if(!enabled||!ctx||ctx.state!=='running')return;const notes={correct:[523,659,784,1047],wrong:[330,247],timeout:[294,220],finish:[392,523,659,784,1047],start:[392,523,659],intro:[392,523,659,784],click:[660],locked:[587,784],tick:[880],urgent:[1047],points:[440,554,659],rank:[659,784,1047],timeup:[196,147]}[type];if(!notes)return;const now=ctx.currentTime;if(type==='finish'||type==='rank'){for(let i=0;i<12;i++)noise(now+i*.075,.15,.045,master,900+i*70);}if(type==='points'||type==='intro'){for(let i=0;i<5;i++)noise(now+i*.075,.07,.055,master,1100);}notes.forEach((f,i)=>tone(f,now+i*.095,type==='tick'||type==='urgent'?.08:.19,type==='urgent'?.12:.085,type==='urgent'?'triangle':'sine'));}
